import { userSchemaValidation } from "../Validations/UserValidations";
import * as yup from "yup";
import { useForm } from "react-hook-form";
import { useState } from "react";
import { yupResolver } from "@hookform/resolvers/yup";
import { Button, Col, Container, Row, Form } from "reactstrap";
import { Link, useNavigate } from "react-router-dom";
import "./Register.css";

const StudentRegister = () => {
  const [role, setRole] = useState("Student");
  const [name, setname] = useState("");
  const [email, setemail] = useState("");
  const [password, setpassword] = useState("");
  const [confirmPassword, setconfirmPassword] = useState("");

  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm({
    resolver: yupResolver(userSchemaValidation),
  });

  const navigate = useNavigate();

  const onSubmit = (data) => {
    console.log("Form Data:", data);

    // بدل إرسالها للسيرفر، نحفظها مؤقتًا
    localStorage.setItem("userData", JSON.stringify(data));

    alert("✅ Account created successfully (Saved locally).");
    navigate("/login");
  };

  return (
    <Container fluid className="register-container">
      <div className="register-box">
        <h2>
          Create your <span>account</span>
        </h2>

        <p className="choose-role">Please choose your role:</p>
        <div className="role-buttons">
          <button
            type="button"
            className={role === "Student" ? "active" : ""}
            onClick={() => setRole("Student")}
          >
            Student
          </button>
          <button
            type="button"
            className={role === "Company" ? "active" : ""}
            onClick={() => setRole("Company")}
          >
            Company
          </button>
        </div>

        <Form className="div-form" onSubmit={handleSubmit(onSubmit)}>
          <Row>
            <Col md={12}>
              <input
                type="text"
                placeholder="Full Name"
                {...register("name", {
                  value: name,
                  onChange: (e) => setname(e.target.value),
                })}
              />
              <p className="error">{errors.name?.message}</p>
            </Col>
          </Row>

          <Row>
            <Col md={12}>
              <input
                type="email"
                placeholder="you@example.com"
                {...register("email", {
                  value: email,
                  onChange: (e) => setemail(e.target.value),
                })}
              />
              <p className="error">{errors.email?.message}</p>
            </Col>
          </Row>

          <Row>
            <Col md={12}>
              <input
                type="password"
                placeholder="Password"
                {...register("password", {
                  value: password,
                  onChange: (e) => setpassword(e.target.value),
                })}
              />
              <p className="error">{errors.password?.message}</p>
            </Col>
          </Row>

          <Row>
            <Col md={12}>
              <input
                type="password"
                placeholder="Confirm Password"
                {...register("confirmPassword", {
                  value: confirmPassword,
                  onChange: (e) => setconfirmPassword(e.target.value),
                })}
              />
              <p className="error">{errors.confirmPassword?.message}</p>
            </Col>
          </Row>

          <Row>
            <Col md={12}>
              <Button className="signup-btn" type="submit">
                Sign Up
              </Button>
            </Col>
          </Row>

          <p className="login-link">
            Already have an account? <Link to="/login">Log in now!</Link>
          </p>
        </Form>
      </div>
    </Container>
  );
};

export default StudentRegister;
